import json
import novamind_api as nm

res = nm.query("""
SELECT e.thread_id, e.customer_id, c.group_id, e.thread_type, e.turn_number, e.sender, e.day, e.seat_count, e.message_text, e.offer_json,
       s.plan as cur_plan, s.effective_price as cur_price
FROM enterprise_turns e
JOIN customers c ON e.customer_id = c.customer_id
LEFT JOIN subscriptions s ON c.customer_id = s.customer_id AND s.status = 'subscribed'
WHERE e.message_id IN (
    SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id
) AND e.closed = 0 AND e.sender != 'agent'
ORDER BY c.group_id, e.day
""")

deals = []
for r in res['rows']:
    cid = r['customer_id']
    grp = r['group_id']
    turn = r['turn_number']
    ttype = r['thread_type']
    cur_price = float(r['cur_price'] or 0.0)
    try:
        counter_price = float(json.loads(r['offer_json'] or '{}').get('price', 0))
    except Exception:
        counter_price = 0.0

    if ttype in ('churn_prevention', 'renewal', 'plan_change') and cur_price > 0:
        ref = counter_price if counter_price > 0 else cur_price
        if grp == 'E1':
            pA, pB, pC = max(4.5, round(ref * 0.50, 1)), max(7.5, round(ref * 0.75, 1)), max(12.0, round(ref * 0.88, 1))
        elif grp in ('D_E09', 'D_E02'):
            pA, pB, pC = max(8.0, round(ref * 0.50, 1)), max(14.0, round(ref * 0.75, 1)), max(24.0, round(ref * 0.88, 1))
        elif grp == 'E2':
            pA, pB, pC = max(14.0, round(ref * 0.45, 1)), max(24.0, round(ref * 0.72, 1)), max(46.0, round(ref * 0.82, 1))
        elif grp in ('E3', 'D_E07', 'D_E08'):
            pA, pB, pC = max(14.0, round(ref * 0.45, 1)), max(22.0, round(ref * 0.72, 1)), max(34.0, round(ref * 0.82, 1))
        else:
            pA, pB, pC = max(8.0, round(ref * 0.50, 1)), max(15.0, round(ref * 0.75, 1)), max(25.0, round(ref * 0.85, 1))
        offer = [['A', pA], ['B', pB], ['C', pC]]
    elif grp == 'E1':
        if turn == 0:
            offer = [['A', 10.5], ['B', 16.0], ['C', 24.0]]
        else:
            offer = [['A', max(4.5, round(counter_price * 0.75, 1))], ['B', max(7.5, round(counter_price * 1.0, 1))], ['C', max(12.0, round(counter_price * 1.30, 1))]]
    elif grp == 'D_E09':
        if turn == 0:
            offer = [['A', 20.0], ['B', 38.0], ['C', 58.0]]
        else:
            offer = [['A', max(9.0, round(counter_price * 0.75, 1))], ['B', max(16.0, round(counter_price * 1.0, 1))], ['C', max(26.0, round(counter_price * 1.35, 1))]]
    elif grp == 'D_E02':
        if turn == 0:
            offer = [['A', 18.0], ['B', 34.0], ['C', 52.0]]
        else:
            offer = [['A', max(9.0, round(counter_price * 0.75, 1))], ['B', max(16.0, round(counter_price * 1.0, 1))], ['C', max(26.0, round(counter_price * 1.35, 1))]]
    elif grp == 'E2':
        if turn == 0:
            offer = [['A', 28.0], ['B', 52.0], ['C', 78.0]]
        else:
            offer = [['A', max(14.0, round(counter_price * 0.70, 1))], ['B', max(24.0, round(counter_price * 1.0, 1))], ['C', max(46.0, round(counter_price * 1.30, 1))]]
    elif grp == 'E3':
        if turn == 0:
            offer = [['A', 32.0], ['B', 56.0], ['C', 84.0]]
        else:
            offer = [['A', max(16.0, round(counter_price * 0.70, 1))], ['B', max(26.0, round(counter_price * 0.98, 1))], ['C', max(36.0, round(counter_price * 1.18, 1))]]
    elif grp == 'D_E08':
        if turn == 0:
            offer = [['A', 35.0], ['B', 65.0], ['C', 98.0]]
